      }
    },
    {
      "task": "build a chair",
      "criteria": {
        "type": "count_in_box_at_least",
        "description": "Player must place at least 1 oak_stairs block in the floor area to create a chair",
        "box": {"x_min_offset": -2, "x_max_offset": 2, "y_min_offset": 0, "y_max_offset": 2, "z_min_offset": 3, "z_max_offset": 7},
        "block_types": ["oak_stairs"],
        "min_count": 1,
        "notes": "A Minecraft chair is minimally 1 oak_stairs block (the seat). Extended y range (0-2) allows for a back made of slabs or additional stairs. Must be within the floor area."
      }
    }
  ]
